entries[383520] = { ["name"] = "Drakonische Schneidereiabhandlung", ["text"] = "Wirken in 3.5 sek. 2\nReagenzien:\nEifer des Handwerkers (10), Felszahnleder , Glitzerndes Pergament (5), Erweckter Frost , Brünierte Tinte\nEntdeckung:\nBei der Herstellung anderer drakonischer Abhandlungen\nBenötigt:\nSpezialisierung: Archivieren - Drakonische Abhandlungen\n\nDrakonische Schneidereiabhandlung\nWird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schneidereiwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Schneiderei der Dracheninseln\n(25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Schneidern. Kann nur einmal pro Woche gelesen werden.\"" }
