entries[383759] = { ["name"] = "Drakonische Inschriftenkundeabhandlung", ["text"] = "Wirken in 3.5 sek. 2\nReagenzien:\nEifer des Handwerkers (10), Felszahnleder , Glitzerndes Pergament (5), Erweckter Frost , Brünierte Tinte\nSpezialisierung:\nArchivieren - Drakonische Abhandlungen\n\nDrakonische Inschriftenkundeabhandlung\nWird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Inschriftenkundewissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Inschriftenkunde der Dracheninseln\n(25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Inschriftenkundigen. Kann nur einmal pro Woche gelesen werden.\"" }
