entries[383767] = { ["name"] = "Dunkelmondkartensetschachtel: Raureif", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nDunkelmondkartenset: Raureif , Erweckter Frost (10), Krümmrinde (10), Kosmische Tinte (12), Funke (#247)\nOptionale Reagenzien:\nMit Energie erfüllen (#111) , Glorreiche Einsicht (#93) , Dunkelmondsiegel (#202) , Löschsand (#221)\nSpezialisierung:\nArchivieren - Frost\n\nDunkelmondkartensetschachtel: Raureif\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)Schmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz] Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Fügt Eurem Ziel 10372 Frostschaden zu und belegt es für 4-12 Sek. mit 'Erwachender Raureif'. Stirbt das Ziel, solange 'Erwachender Raureif' aktiv ist, explodiert es und verursacht 25929 Frostschaden, der auf Gegner innerhalb eines Radius von 10 Metern aufgeteilt wird. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)" }
entries[383768] = { ["name"] = "Verrottende Verderbnis" }
entries[383770] = { ["name"] = "Dunkelmondkartensetschachtel: Tanz", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nDunkelmondkartenset: Tanz , Erweckte Luft (10), Krümmrinde (10), Kosmische Tinte (12), Funke (#247)\nOptionale Reagenzien:\nMit Energie erfüllen (#111) , Glorreiche Einsicht (#93) , Dunkelmondsiegel (#202) , Löschsand (#221)\nSpezialisierung:\nArchivieren - Luft\n\nDunkelmondkartensetschachtel: Tanz\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)Schmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz] Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Ein 'Erfrischender Tanz' springt 6-13-mal zwischen Freunden und Gegnern innerhalb von 25 Metern hin und her und verursacht 6228 Naturschaden oder heilt um 4133 Gesundheit. Die Anzahl der Sprünge wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)" }
entries[383771] = { ["name"] = "S.E.L.F.I.E." }
entries[383772] = { ["name"] = "Dunkelmondkartensetschachtel: Behüter", ["text"] = "Wirken in 5 sek. 3\nReagenzien:\nDunkelmondkartenset: Behüter , Erweckte Erde (10), Krümmrinde (10), Kosmische Tinte (12), Funke (#247)\nOptionale Reagenzien:\nMit Energie erfüllen (#111) , Glorreiche Einsicht (#93) , Dunkelmondsiegel (#202) , Löschsand (#221)\nSpezialisierung:\nArchivieren - Erde\n\nDunkelmondkartensetschachtel: Behüter\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)Schmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz] Anlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Gewährt 5-12 Sek. lang den 'Segen des Behüters' und einen Absorptionsschild in Höhe von 51162 Schaden.\nWenn der Schild verbraucht wird, während 'Segen des Behüters' aktiv ist, wird für dieselbe Dauer 1230 Vielseitigkeit gewährt. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)" }
