entries[383925] = { ["name"] = "Kältesturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nMelidrussa beschwört einen anwachsenden Froststurm am Standort eines Spielercharakters, der Spielercharaktere zu sich hin zieht.\n\nAlle 1 Sek. fügt der Sturm allen Spielercharakteren 727335 Frostschaden zu. Zusätzlich fügt der Sturm allen Spielercharakteren, die sich im Effektbereich des Sturms aufhalten, 3636674 Frostschaden zu.\n\nNach 6 Sek. explodiert der Sturm, fügt allen Spielercharakteren 2909339 Frostschaden zu und stößt sie zurück." }
entries[383926] = { ["name"] = "An Feuer und Flamme gebunden", ["text"] = "Sofort 2 min Abklingzeit\nCa. 12 Procs pro Minute\nBindet Euch 20 Sek. lang an die Flamme, wodurch Eure Angriffe eine hohe Chance haben, Eure Stärke um 33 zu erhöhen. Bis zu 6-mal stapelbar. Wenn die Bindung vervollständigt wurde, sondert Ihr eine ausbrennende Welle ab, die abhängig von der Stärke Eurer Bindung bis zu 3775 Feuerschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird.\n(500ms Abklingzeit)" }
