entries[384019] = { ["name"] = "Feuriger Fokus", ["text"] = "100 Meter Reichweite\nSofort\nBei Erreichen von 100 Energie fixiert sich Chargath auf sein Primärziel und entfesselt 25 Sek. lang einen Hagel aus Magmaangriffen.\n\nSolange $@spellname375056 aktiv ist, fügt Chargath dem anvisierten Spielercharakter alle 1 Sek. 2424449 körperlichen Schaden und 3636674 Feuerschaden zu und stößt alle 1 Sek. Lavaspritzer aus.\n\nChargath entfesselt eine Magmawelle, wenn ' Feuriger Fokus ' nicht unterbrochen wird, und belegt alle Spielercharaktere mit ' Flammender Untergang '.", ["unresolvedValues"] = true }
