entries[384625] = { ["name"] = "Überwältigende Energie", ["text"] = "Sofort\nAzurklinge bewegt sich in die Mitte des Raums und beginnt, Macht aus dem drakonischen Siegel zu erhalten. Sie schützt sich selbst mit 'Drakonische Illusion' und fügt allen Spielercharakteren alle 2.5 Sek. 1212225 Arkanschaden zu, bis alle Illusionen zerstört wurden." }
