entries[384631] = { ["name"] = "Geißelung", ["text"] = "Nahkampfreichweite\nSofort 1.5 min Abklingzeit\nPeitscht das Ziel und fügt ihm so (60% der Angriffskraft) Schattenschaden zu. Zusätzlich löst jeder innerhalb von 12 Sek. verbrauchte Combopunkt einen weiteren Peitschenhieb aus, der (12.1% der Angriffskraft) Schaden verursacht. Wenn Ihr Schaden mit 'Geißelung' verursacht, wird Eure Meisterschaft um ( 10 / 10 * [Quellwert] as)% erhöht. Dieser Effekt hält nach Ende der Qual des Ziels noch 12 Sek. lang an.\n(100ms Abklingzeit)", ["unresolvedValues"] = true }
entries[384633] = { ["name"] = "Ruf der Herrin", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nBauchschuss ruft ihre Faulbisshyänen zu sich und befreit sie aus der Schlingenfalle . Die Hyänen werden gegen alle Effekte dieser Art immun, und ihre Bewegungsgeschwindigkeit ist 5 Sek. lang um 15% erhöht." }
