entries[384637] = { ["name"] = "Tobende Winde", ["text"] = "200 Meter Reichweite\nSofort\n' Wütender Gewittersturm ' stößt in regelmäßigen Abständen angestaute Winde aus, die allen Spielercharakteren alle 4 Sek. 3180 Naturschaden zufügen." }
