entries[384639] = { ["name"] = "Geschwindigkeitsbereich durch 'Trampelnde Hufe'", ["text"] = "Sofort\nEure Angriffe haben eine Chance, einen trampelnden Zentauren vorwärtsstürmen zu lassen. Dieser verursacht 0 körperlichen Schaden, der auf alle Gegner in einer Linie aufgeteilt wird. Der Zentaur hinterlässt für bis Abbruch eine geisterhafte Spur, die Eure Bewegungsgeschwindigkeit und die Eurer Gruppenmitglieder um 0% erhöht." }
