entries[384649] = { ["name"] = "Kyrakkas sengende Glut", ["text"] = "Ca. 4 Procs pro Minute\nEure hilfreichen Zauber und Fähigkeiten haben eine hohe Chance, bei einem Verbündeten eine 'Brennende Glut' zu entfachen. Nach 1 Sek. lodert die Glut auf, heilt durch das Kauterisieren von Wunden um 1215 Gesundheit und verursacht 476 Feuerschaden, der auf Gegner in der Nähe aufgeteilt wird.\n(1s Abklingzeit)" }
