entries[384686] = { ["name"] = "Energiewoge", ["text"] = "Wirken in 1.5 sek.\nIm wütenden Gewittersturm steigt eine Energiewoge empor, die sein Nahkampfangriffstempo 8 Sek. lang um 100% erhöht und Nahkampfangriffe zusätzlich 1212225 Naturschaden verursachen lässt." }
