entries[384688] = { ["name"] = "Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet." }
entries[384689] = { ["name"] = "Teilen und herrschen", ["text"] = "[ Atem der Äonen : 'Atem der Äonen' / 'Tiefer Atem'] bildet Schleier aus Feuer, die Gegnern auf der anderen Seite die Sichtlinie blockieren und Gegnern, die sie durchqueren, verbrennen und so (480% der Zaubermacht) Feuerschaden zufügen. Hält 6 Sek. lang an." }
entries[384690] = { ["name"] = "Geschmolzenes Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nSie sind manchmal in Flammen gehüllt, besonders in seismisch aktiven Gebieten. Ihre unerträgliche Hitze hält Anfänger oft davon ab, ihr reiches Vorkommen an tobendem Feuer abzubauen.\n\nDie Spezialisierung auf geschmolzene Vorkommen gewährt beim Abbauen den folgenden Effekt:\n\nGlühender Zorn :\nHüllt Euch in Flammen und lässt Eure Angreifer 1721 Feuerschaden erleiden. Hält 2 Min. lang an." }
entries[384691] = { ["name"] = "Teilen und herrschen", ["text"] = "100 Meter Reichweite\nSofort\n'Tiefer Atem' bildet 8 Sek. lang eine Feuerwand, die die Sichtlinie blockiert. Gegner, die die Wand durchqueren, erleiden 1 Schaden." }
entries[384692] = { ["name"] = "Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\nBeruf:\nBergbau (1)" }
entries[384693] = { ["name"] = "Reiches Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nReiche Vorkommen sind besonders ergiebig an Erzen und sicher eine Freude für jeden Bergarbeiter, der sie entdeckt." }
entries[384694] = { ["name"] = "Aufkommendes Frösteln", ["text"] = "Sofort 3 min Abklingzeit\nRuft eine erweckende Kälte hervor, die 0-4 Frostschaden in einem kegelförmigen Bereich verursacht und Gegner 4 Sek. lang um 50% verlangsamt. Der verursachte Schaden wird durch die oberste Karte des Sets bestimmt.\n\nAnlegen: Mischt im Kampf regelmäßig das Kartenset." }
