entries[384713] = { ["name"] = "Phiole der aufgeladenen Isolation", ["text"] = "Sofort\nEuer Primärwert ist um 51 erhöht, solange Ihr mindestens 10 Meter von Verbündeten entfernt seid. Nachdem Ihr in der Nähe eines Verbündeten wart, bleiben Euch 75% dieses Werts 2.5 Sek. lang erhalten.\n\nHält 30 Min. lang und über den Tod hinaus an. Die Benutzung einer identischen Phiole verlängert die Dauer um 30 Min." }
entries[384715] = { ["name"] = "Mit Federn bedeckt", ["text"] = "Sofort\nLeicht wie eine Feder. Erhöht die Bewegungsgeschwindigkeit um 100% und das Tempo um 30%." }
